export const SCRIPT_OVERLOAD_DISPATCH_FACTS = "defold-script-overload-dispatch-recipe-facts.json";

function validate(facts) {
  if (
    facts?.schemaVersion !== 1 ||
    facts.kind !== "deherm.recipe.script-overload-dispatch-output" ||
    !Array.isArray(facts.bindings) ||
    !Array.isArray(facts.nativeBindings) ||
    facts.nativeBindings.some((row, index) => row.index !== index || !Array.isArray(row.callShapes))
  ) {
    throw new Error("Unsupported script overload-dispatch recipe facts");
  }
  return facts;
}
const cpp = (value) => JSON.stringify(value);
const mask = (codec) => `k${codec}`;

export function createScriptOverloadDispatchRecipeFacts(report) {
  const bindings = report.bindings.map(({ id, stableId, generatedFamilyExecutableCandidate, targetSupport }) => ({
    id,
    stableId,
    generatedFamilyExecutableCandidate,
    targetSupport,
  }));
  const nativeBindings = report.bindings
    .filter(({ generatedFamilyExecutableCandidate }) => generatedFamilyExecutableCandidate)
    .map(({ id, stableId, modulePath, member, callShapes }, index) => ({
      index,
      id,
      stableId,
      modulePath,
      member,
      callShapes,
    }));
  return {
    schemaVersion: 1,
    kind: "deherm.recipe.script-overload-dispatch-output",
    bindings,
    nativeBindings,
  };
}

function renderNative(rows) {
  if (rows.length > 0xffff) throw new Error("overload-dispatch operation count exceeds uint16_t descriptor capacity");
  const operations = rows.map((row, index) => ({ ...row, index }));
  const shapes = [];
  const argumentCodecs = [];
  for (const operation of operations) {
    if (operation.index > 0xffff)
      throw new Error(`${operation.id}: operation index exceeds uint16_t descriptor capacity`);
    if (operation.callShapes.length > 0xff)
      throw new Error(`${operation.id}: call-shape count exceeds uint8_t descriptor capacity`);
    if (shapes.length > 0xffff) throw new Error(`${operation.id}: shape offset exceeds uint16_t descriptor capacity`);
    operation.shapeOffset = shapes.length;
    for (const shape of operation.callShapes) {
      if (shape.arguments.length > 0xff)
        throw new Error(`${operation.id}: call-shape argument count exceeds uint8_t descriptor capacity`);
      if (argumentCodecs.length > 0xffff)
        throw new Error(`${operation.id}: argument-codec offset exceeds uint16_t descriptor capacity`);
      shapes.push({
        argumentOffset: argumentCodecs.length,
        argumentCount: shape.arguments.length,
        resultCodec: shape.resultCodec,
      });
      argumentCodecs.push(...shape.arguments);
    }
  }
  if (shapes.length > 0xffff) throw new Error("overload-dispatch shape table exceeds uint16_t descriptor capacity");
  if (argumentCodecs.length > 0xffff)
    throw new Error("overload-dispatch argument-codec table exceeds uint16_t descriptor capacity");
  const header = `// Generated by scripts/generate-script-overload-dispatch.mjs. Do not edit.\n#pragma once\n\n#include <cstddef>\n#include <cstdint>\n#include <defold_hermes/script_bridge_capi.hpp>\n\nnamespace defold_hermes::overload_dispatch {\nenum class DispatchStatus : uint8_t { kMissing, kSuccess, kError };\nenum CodecMask : uint16_t { kNumber=1u<<0, kVector3=1u<<1, kVector4=1u<<2, kQuaternion=1u<<3, kMatrix4=1u<<4 };\nstruct Operation { uint16_t index; uint32_t stableId; const char* canonicalId; const char* modulePath; const char* member; uint16_t shapeOffset; uint8_t shapeCount; };\nstruct Shape { uint16_t argumentOffset; uint8_t argumentCount; uint16_t resultMask; };\nstruct LuaApi { void* context = nullptr; DispatchStatus (*invoke)(void*, const Operation&, const Shape&, ScriptCallFrame*, char*, size_t) noexcept = nullptr; };\ninline constexpr size_t kBindingCount = ${operations.length};\nconst Operation* operations() noexcept;\nconst Operation* find(uint32_t stableId) noexcept;\nconst Shape* shapes() noexcept;\nconst uint16_t* argumentCodecs() noexcept;\nDispatchStatus dispatch(ScriptCallFrame*, char*, size_t, const LuaApi*) noexcept;\n}\n`;
  const operationEntries = operations.length
    ? operations
        .map(
          (row) =>
            `  {${row.index}, ${row.stableId}u, ${cpp(row.id)}, ${cpp(row.modulePath.join("."))}, ${cpp(row.member)}, ${row.shapeOffset}, ${row.callShapes.length}},`,
        )
        .join("\n")
    : "  {},  // sentinel storage; kBindingCount remains zero";
  const shapeEntries = shapes.length
    ? shapes
        .map((shape) => `  {${shape.argumentOffset}, ${shape.argumentCount}, ${mask(shape.resultCodec)}},`)
        .join("\n")
    : "  {},  // sentinel storage";
  const codecEntries = argumentCodecs.length
    ? argumentCodecs.map((codec) => `  ${mask(codec)},`).join("\n")
    : "  0,  // sentinel storage";
  const source = `// Generated by scripts/generate-script-overload-dispatch.mjs. Do not edit.\n#include <defold_hermes/generated_script_overload_dispatch.hpp>\n#include <cstdio>\n\nnamespace defold_hermes::overload_dispatch { namespace {\nconstexpr Operation kOperations[] = {\n${operationEntries}\n};\nconstexpr Shape kShapes[] = {\n${shapeEntries}\n};\nconstexpr uint16_t kArgumentCodecs[] = {\n${codecEntries}\n};\nvoid fail(char* error,size_t capacity,const char* message) noexcept { if(error&&capacity) std::snprintf(error,capacity,"%s",message); }\nuint16_t valueMask(const ScriptValue& value) noexcept {\n  if(value.tag==ScriptValueTag::kNumber)return kNumber;\n  if(value.tag!=ScriptValueTag::kDefoldValue)return 0;\n  switch(value.defoldKind){case ScriptDefoldValueKind::kVector3:return kVector3;case ScriptDefoldValueKind::kVector4:return kVector4;case ScriptDefoldValueKind::kQuaternion:return kQuaternion;case ScriptDefoldValueKind::kMatrix4:return kMatrix4;default:return 0;}\n}\nbool matches(const Shape& shape,const ScriptCallFrame& frame) noexcept { if(frame.argumentCount!=shape.argumentCount||(frame.argumentCount&&!frame.arguments))return false;for(uint32_t index=0;index<frame.argumentCount;++index)if(!(valueMask(frame.arguments[index])&kArgumentCodecs[shape.argumentOffset+index]))return false;return true; }\n}\nconst Operation* operations() noexcept{return kOperations;}\nconst Operation* find(uint32_t stableId) noexcept { size_t first=0,count=kBindingCount;while(count){const size_t step=count/2,index=first+step;if(kOperations[index].stableId<stableId){first=index+1;count-=step+1;}else count=step;}return first<kBindingCount&&kOperations[first].stableId==stableId?&kOperations[first]:nullptr;}\nconst Shape* shapes() noexcept{return kShapes;}\nconst uint16_t* argumentCodecs() noexcept{return kArgumentCodecs;}\nDispatchStatus dispatch(ScriptCallFrame* frame,char* error,size_t capacity,const LuaApi* api) noexcept {\n  if(!frame){fail(error,capacity,"Overload-dispatch call frame is null");return DispatchStatus::kError;}const Operation* operation=find(frame->stableId);if(!operation)return DispatchStatus::kMissing;frame->resultCount=0;const Shape* selected=nullptr;for(uint8_t index=0;index<operation->shapeCount;++index){const Shape& shape=kShapes[operation->shapeOffset+index];if(matches(shape,*frame)){selected=&shape;break;}}if(!selected){fail(error,capacity,"Overload-dispatch arguments do not match a reviewed call shape");return DispatchStatus::kError;}if(!frame->results||frame->resultCapacity<1){fail(error,capacity,"Overload-dispatch result storage is exhausted");return DispatchStatus::kError;}if(!api||!api->invoke){fail(error,capacity,"Overload-dispatch Lua backend is unavailable");return DispatchStatus::kError;}const DispatchStatus status=api->invoke(api->context,*operation,*selected,frame,error,capacity);if(status!=DispatchStatus::kSuccess){frame->resultCount=0;return status==DispatchStatus::kMissing?DispatchStatus::kError:status;}if(frame->resultCount!=1||!(valueMask(frame->results[0])&selected->resultMask)){frame->resultCount=0;fail(error,capacity,"Overload-dispatch Lua result does not match the reviewed call shape");return DispatchStatus::kError;}return DispatchStatus::kSuccess;\n}\n}\n`;
  return { header, source };
}

export function renderScriptOverloadDispatchOutputs(input) {
  const facts = validate(input);
  const native = renderNative(facts.nativeBindings);
  const bindings = facts.bindings.map(({ id, stableId, generatedFamilyExecutableCandidate, targetSupport }) => ({
    id,
    stableId,
    generatedFamilyExecutableCandidate,
    targetSupport: {
      nativeDynamicHermes: targetSupport.nativeDynamicHermes,
      nativeStaticHermes: targetSupport.nativeStaticHermes,
      html5BrowserHost: targetSupport.html5BrowserHost,
    },
  }));
  const target = `// Generated by scripts/generate-script-overload-dispatch.mjs. Do not edit.\nexport const scriptOverloadDispatchTargetSupport = ${JSON.stringify(bindings, null, 2)} as const;\nexport const scriptOverloadDispatchCandidateIds = ${JSON.stringify(
    facts.nativeBindings.map(({ id }) => id),
    null,
    2,
  )} as const;\nexport function assertOverloadDispatchTargetSupport(target: string | undefined, canonicalId: string): void {\n  const entry = scriptOverloadDispatchTargetSupport.find(({ id }) => id === canonicalId);\n  if (!entry) return;\n  if (target === "html5-browser-host") throw new Error(\`${"${canonicalId}"} is not executable in the HTML5 browser host: no generated overload-dispatch provider\`);\n  if (!entry.generatedFamilyExecutableCandidate) throw new Error(\`${"${canonicalId}"} is blocked: ${"${entry.targetSupport.nativeDynamicHermes}"}\`);\n}\n`;
  return { header: native.header, source: native.source, target };
}
